/**
 * Fingerprint actual portable files through the same bounded descriptor reader used by the application.
 * This is a before/after integrity observation, not an atomic directory snapshot or authentication.
 * Symbol index (generated by tools/update-symbol-index.ts):
 * @@SYMBOL_INDEX_START
 * - variable fs: line 13
 * - variable path: line 14
 * - variable DEFAULTS: line 17
 * - function payloadHashes: line 23
 * @@SYMBOL_INDEX_END
 */
"use strict";
const fs = require("node:fs/promises");
const path = require("node:path");
const { createHash } = require("node:crypto");
const { ancestors, readRegular } = require("../files.cjs");
const DEFAULTS = Object.freeze({
  maxEntries: 1024,
  maxFileBytes: 512 * 1024 * 1024,
  maxTotalBytes: 1024 * 1024 * 1024,
});

async function payloadHashes(directory, limits = DEFAULTS) {
  if (
    !limits ||
    Object.keys(limits).sort().join("|") !== Object.keys(DEFAULTS).sort().join("|") ||
    Object.keys(DEFAULTS).some(
      (key) => !Number.isSafeInteger(limits[key]) || limits[key] < 1 || limits[key] > DEFAULTS[key],
    )
  )
    throw new Error("Invalid bounded payload limits.");
  const result = {};
  let count = 0,
    total = 0;
  async function walk(current) {
    ancestors(current);
    const entries = await fs.opendir(current);
    for await (const entry of entries) {
      if (++count > limits.maxEntries)
        throw new Error("Portable inventory exceeds its entry budget.");
      const name = path.join(current, entry.name);
      if (entry.isSymbolicLink()) throw new Error("Portable aliases are unsupported.");
      if (entry.isDirectory()) {
        await walk(name);
        continue;
      }
      // readRegular opens first, then binds named and descriptor identities and every bounded byte.
      // Never use earlier pathname stat metadata to size a later file open.
      const bytes = readRegular(name, Math.min(limits.maxFileBytes, limits.maxTotalBytes - total));
      total += bytes.length;
      result[path.relative(directory, name).replaceAll("\\", "/")] = createHash("sha256")
        .update(bytes)
        .digest("hex");
    }
  }
  await walk(directory);
  return result;
}
module.exports = { payloadHashes, DEFAULTS };
